"""Semantic version sorting per SemVer 2.0.0 precedence."""


def _identifier_key(ident):
    # Numeric identifiers sort below alphanumeric ones; numeric compare as ints,
    # alphanumeric compare in ASCII order.
    if ident.isdigit():
        return (0, int(ident), "")
    return (1, 0, ident)


def _version_key(version):
    # Build metadata (after '+') is ignored for precedence.
    core_and_pre = version.split("+", 1)[0]

    # Pre-release begins at the first hyphen.
    if "-" in core_and_pre:
        core, pre = core_and_pre.split("-", 1)
    else:
        core, pre = core_and_pre, None

    major, minor, patch = (int(part) for part in core.split("."))

    if pre is None:
        # A release version ranks above any pre-release of the same core.
        pre_key = (1, ())
    else:
        # Tuple comparison handles the shorter-list-is-lower rule naturally.
        pre_key = (0, tuple(_identifier_key(i) for i in pre.split(".")))

    return (major, minor, patch, pre_key)


def sort_versions(vs):
    """Return the version strings sorted lowest precedence first.

    Python's sort is stable, so versions with equal precedence keep their
    input order.
    """
    return sorted(vs, key=_version_key)
